<script setup>
import { computed, onMounted, ref } from "vue";
import { CalendarCheck, Check, LoaderCircle, RefreshCw, Trash2, X } from "lucide-vue-next";
import { api } from "../api/client";
const props = defineProps({ role: { type: String, default: "teacher" } }); const date = ref(new Date().toISOString().slice(0,10)); const mode = ref(props.role === "teacher" ? "take" : "view"); const classroom = ref(null); const students = ref([]); const records = ref([]); const pending = ref([]); const message = ref(""); const error = ref(""); const loading = ref(true); const isAdmin = computed(() => props.role === "admin");
async function load() { loading.value = true; try { if (isAdmin.value) { const data = await api.get(`/admin/attendances${date.value ? `?date=${date.value}` : ""}`, "admin"); records.value = Array.isArray(data) ? data : []; } else { const teacher = await api.get(`/teachers/${localStorage.getItem("teacher")}`, "teacher"); classroom.value = teacher?.classroom || null; students.value = teacher?.classroom?.students || []; await prepareRollCall(); } } catch (cause) { error.value = cause.message || "考勤数据加载失败"; } finally { loading.value = false; } }
async function prepareRollCall() { if (!date.value || !students.value.length) return; const data = await api.get(`/attendances?date=${date.value}`, "teacher"); records.value = Array.isArray(data) ? data : []; const recorded = new Set(records.value.map((item) => item.student_id)); pending.value = students.value.filter((student) => !recorded.has(student.id)); if (!pending.value.length && records.value.length) message.value = "该日期已完成考勤"; }
async function record(student, status) { try { await api.post("/attendances", { student_id: student.id, status, date: date.value }, "teacher"); message.value = status === "Present" ? "已记录出勤" : "已记录缺勤"; await prepareRollCall(); } catch (cause) { error.value = cause.message || "考勤记录失败"; } }
async function remove(id) { try { await api.delete(`/admin/attendances/${id}`, "admin"); message.value = "考勤记录已删除"; await load(); } catch (cause) { error.value = cause.message || "删除失败"; } }
onMounted(load);
</script>
<template><div><div class="page-heading"><div><span class="mono-label">{{ isAdmin ? 'ADMIN / 考勤' : '班级 / 考勤' }}</span><h1>{{ isAdmin ? '全园考勤' : '本班考勤' }}</h1><p>{{ isAdmin ? '按日期观察并维护全园考勤记录。' : '逐个完成本班签到，保持每天的记录完整。' }}</p></div><button class="button button-dark" @click="load"><RefreshCw :size="15" />刷新</button></div><div v-if="message" class="notice" style="margin-bottom:14px">{{ message }}</div><div v-if="error" class="notice error" style="margin-bottom:14px">{{ error }}</div><section class="surface surface-pad"><div class="toolbar"><div class="filter-row"><div class="field" style="grid-column:auto"><label for="attendance-date">日期</label><input id="attendance-date" v-model="date" type="date" class="filter-input" style="min-width:160px" @change="isAdmin ? load() : prepareRollCall()" /></div><div class="chip-row" style="align-self:end"><button class="chip" :class="{ active: mode === 'take' }" type="button" @click="mode='take'; prepareRollCall()">记录考勤</button><button class="chip" :class="{ active: mode === 'view' }" type="button" @click="mode='view'; isAdmin ? load() : null">查看记录</button></div></div><span v-if="!isAdmin" class="mono-label">{{ classroom?.name || '未分配班级' }}</span></div></section><div v-if="loading" class="empty-state"><LoaderCircle class="spin" :size="28" /></div><template v-else-if="!isAdmin && mode === 'take'"><div v-if="!classroom" class="notice error" style="margin-top:16px">你还没有分配班级，请联系管理员。</div><div v-else-if="!pending.length" class="empty-state"><Check :size="28" style="margin-bottom:10px; color:#31ad9d" /><strong>该日期已完成点名</strong><span>切换到“查看记录”查看详细名单。</span></div><div v-else style="display:grid; gap:9px; margin-top:16px"><article v-for="student in pending" :key="student.id" class="surface surface-pad" style="display:flex; align-items:center; justify-content:space-between; gap:14px"><div><span class="mono-label">{{ student.admission_number }}</span><strong style="display:block; margin-top:5px; color:inherit">{{ student.first_name }} {{ student.second_name }} {{ student.surname }}</strong></div><div class="row-actions"><button class="button button-light" @click="record(student,'Present')"><Check :size="15" />出勤</button><button class="button button-danger" @click="record(student,'Absent')"><X :size="15" />缺勤</button></div></article></div></template><section v-else class="surface" style="margin-top:16px"><div class="surface-title" style="padding:18px 18px 0"><h2>{{ date }} 考勤名单</h2><span>{{ records.length }} 条记录</span></div><div v-if="!records.length" class="empty-state">该日期暂无考勤记录</div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>日期</th><th>学生</th><th>状态</th><th v-if="isAdmin">操作</th></tr></thead><tbody><tr v-for="item in records" :key="item.id"><td>{{ item.date }}</td><td>{{ item.student_name }}</td><td><span class="status" :class="item.status === 'Present' ? 'ok' : 'warn'">{{ item.status === 'Present' ? '出勤' : '缺勤' }}</span></td><td v-if="isAdmin"><button class="row-action" style="color:#ad5148" @click="remove(item.id)"><Trash2 :size="13" /></button></td></tr></tbody></table></div></section></div></template>
<style scoped>.spin { animation: spin 1s linear infinite; } @keyframes spin { to { transform:rotate(360deg); } }</style>
